 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { Link, useNavigate } from 'react-router-dom'
import { 
  Trophy, 
  Medal, 
  Crown, 
  Users, 
  TrendingUp,
  Calendar,
  Heart,
  CheckCircle,
  Home,
  Plane,
  Minus
} from 'lucide-react'
import VerifiedBadge from '../components/VerifiedBadge'
import { checkUserSubscription } from '../services/subscriptionService'

export default function Leaderboard() {
    const { user } = useAuth()
    const navigate = useNavigate()
    const [predictions, setPredictions] = useState([])
    const [loading, setLoading] = useState(true)
    const [timeFrame, setTimeFrame] = useState('today')
    const [isSubscribed, setIsSubscribed] = useState(false)
    const [checking, setChecking] = useState(true)

    // Check subscription first
    useEffect(() => {
        const checkAccess = async () => {
            if (!user) {
                navigate('/login')
                return
            }
            
            const subscribed = await checkUserSubscription(user.id)
            setIsSubscribed(subscribed)
            setChecking(false)

            // ✅ FIX: Only redirect if we are NOT already on the subscribe page
            if (!subscribed && window.location.pathname !== '/subscribe') {
                navigate('/subscribe')
            }
        }
        checkAccess()
    }, [user, navigate])

    useEffect(() => {
        if (isSubscribed) {
            loadLeaderboard()
        }
    }, [timeFrame, isSubscribed])

    const loadLeaderboard = async () => {
        setLoading(true)
        try {
            const now = new Date()
            let startDate = new Date()
            
            if (timeFrame === 'today') {
                startDate.setHours(0, 0, 0, 0)
            } else if (timeFrame === 'week') {
                startDate.setDate(now.getDate() - 7)
            } else if (timeFrame === 'month') {
                startDate.setMonth(now.getMonth() - 1)
            }

            const startDateStr = startDate.toISOString()
            const endDateStr = now.toISOString()

            const { data, error } = await supabase
                .from('public_predictions')
                .select(`
                    *,
                    profiles:user_id (id, username, full_name, avatar_url, points, is_verified)
                `)
                .gte('created_at', startDateStr)
                .lte('created_at', endDateStr)
                .order('likes_count', { ascending: false })
                .limit(10)

            if (error) throw error
            setPredictions(data || [])
        } catch (error) {
            console.error('Error loading leaderboard:', error)
            setPredictions([])
        } finally {
            setLoading(false)
        }
    }

    // While checking subscription, show a loading state
    if (checking) {
        return (
            <div className="min-h-[60vh] flex items-center justify-center">
                <div className="text-center">
                    <div className="text-xl text-gray-500">Checking subscription...</div>
                </div>
            </div>
        )
    }

    // If not subscribed and we are NOT on the subscribe page, redirect happens in useEffect
    // This prevents the component from rendering the wrong content
    if (!isSubscribed) return null

    const formatDate = (date) => {
        return new Date(date).toLocaleDateString('en-US', {
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        })
    }

    const getMedal = (index) => {
        if (index === 0) return <Crown className="w-8 h-8 text-yellow-500" />
        if (index === 1) return <Medal className="w-8 h-8 text-gray-400" />
        if (index === 2) return <Medal className="w-8 h-8 text-amber-600" />
        return <span className="text-gray-400 font-bold">#{index + 1}</span>
    }

    const getResultIcon = (result) => {
        if (result === 'Home Win') return <Home size={16} className="text-green-600" />
        if (result === 'Away Win') return <Plane size={16} className="text-blue-600" />
        return <Minus size={16} className="text-gray-400" />
    }

    const renderPrediction = (pred, index) => {
        const data = pred.prediction_data || {}
        const isOwn = user?.id === pred.user_id
        
        return (
            <div 
                key={pred.id} 
                className={`bg-white rounded-xl shadow-md p-4 hover:shadow-lg transition flex items-start gap-4 ${
                    isOwn ? 'border-2 border-green-500' : ''
                }`}
            >
                <div className="flex items-center justify-center w-12 h-12 flex-shrink-0">
                    {getMedal(index)}
                </div>

                <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold">
                            {pred.profiles?.username?.[0]?.toUpperCase() || 'U'}
                        </div>
                        <div>
                            <div className="font-semibold flex items-center gap-1.5">
                                {pred.profiles?.full_name || pred.profiles?.username || 'Unknown'}
                                {pred.profiles?.is_verified && <VerifiedBadge size="sm" />}
                                {isOwn && (
                                    <span className="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded-full flex items-center gap-1">
                                        <CheckCircle size={12} /> You
                                    </span>
                                )}
                            </div>
                            <div className="text-sm text-gray-500">@{pred.profiles?.username || 'user'}</div>
                        </div>
                    </div>

                    <div className="bg-gray-50 rounded-lg p-3 mb-2">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                {getResultIcon(data.result)}
                                <span className="font-bold">{data.result || 'Draw'}</span>
                            </div>
                            <div className="flex items-center gap-3 text-sm text-gray-500">
                                <span className="flex items-center gap-1">
                                    <span className="text-yellow-500">🟨</span> {data.yellowCards || 0}
                                </span>
                                <span className="flex items-center gap-1">
                                    <span className="text-red-500">🟥</span> {data.redCards || 0}
                                </span>
                                <span className="flex items-center gap-1">
                                    <span className="text-gray-500">🏁</span> {data.corners || 0}
                                </span>
                            </div>
                        </div>
                    </div>

                    <div className="flex items-center justify-between text-sm">
                        <div className="flex items-center gap-4">
                            <span className="text-red-500 font-medium flex items-center gap-1">
                                <Heart size={14} fill="currentColor" /> {pred.likes_count || 0}
                            </span>
                            <span className="text-gray-400 flex items-center gap-1">
                                <Calendar size={14} /> {formatDate(pred.created_at)}
                            </span>
                        </div>
                        <Link 
                            to="/matches"
                            className="text-xs text-green-600 hover:underline"
                        >
                            View Match →
                        </Link>
                    </div>
                </div>
            </div>
        )
    }

    return (
        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                        <Trophy size={24} className="text-yellow-500" /> Leaderboard
                    </h1>
                    <p className="text-gray-500">Top 10 most liked predictions</p>
                </div>
                
                <div className="flex gap-2">
                    <button
                        onClick={() => setTimeFrame('today')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-1 ${
                            timeFrame === 'today' 
                                ? 'bg-green-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        <TrendingUp size={16} /> Today
                    </button>
                    <button
                        onClick={() => setTimeFrame('week')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            timeFrame === 'week' 
                                ? 'bg-green-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        This Week
                    </button>
                    <button
                        onClick={() => setTimeFrame('month')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            timeFrame === 'month' 
                                ? 'bg-green-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        This Month
                    </button>
                </div>
            </div>

            {loading ? (
                <div className="text-center py-12">
                    <div className="text-gray-500">Loading leaderboard...</div>
                </div>
            ) : predictions.length === 0 ? (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    <Trophy className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                    <p className="text-gray-500">No predictions yet</p>
                    <p className="text-sm text-gray-400">Be the first to share a prediction and get likes!</p>
                    <Link 
                        to="/matches"
                        className="inline-block mt-4 bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700"
                    >
                        Share a Prediction →
                    </Link>
                </div>
            ) : (
                <div className="space-y-4">
                    {predictions.map((pred, index) => renderPrediction(pred, index))}
                </div>
            )}

            {!loading && predictions.length > 0 && (
                <div className="text-center text-sm text-gray-400 mt-6">
                    Showing top {predictions.length} predictions
                </div>
            )}
        </div>
    )
}
